import type { Source } from "./Core";
/**
 * Callbag operator that delays the emission of items from
 * the source by a given timeout or until a given date.
 * Works on either pullable and listenable sources.
 *
 * Marble diagram:
 *   "a b c |"
 *   {delay(5)}
 *   "5ms a b c |"
 *
 * @param due The delay duration in milliseconds (a number)
 *   or a Date until which the emission of the source items
 *   is delayed.
 *
 * @internal
 */
export declare const delay: <T, E>(due: number | Date) => (source: Source<T, E>) => Source<T, E>;
